from check import release,frame
import pyogrio
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
OUT=ROOT/'RAPID/outputs/proposed_boundary_fixes_20261027';OLD=ROOT/'RAPID/outputs/review_notes_20261027'
proposals=json.loads((OUT/'proposals.json').read_text());cache={}
for c in proposals:
 key=c['key'];ex,state=key.split('/');audit=c['graph_check'];c['proposal_id']=hashlib.sha256(json.dumps(c,sort_keys=True).encode()).hexdigest()[:16]
 img=OLD/(key.replace('/','_')+'.png')
 if not img.exists() and ex=='02':img=OLD/'02_S004_unit_5.png'
 c['evidence_image']='data:image/png;base64,'+base64.b64encode(img.read_bytes()).decode() if img.exists() else None
 if not audit:continue
 r=release.lookup(ex,'indep',state);f=frame(r['original_frame']).set_index('id_link');g=pyogrio.read_dataframe(r['links']).set_index('id_link');nodes=pyogrio.read_dataframe(r['nodes']).set_index('id_node');mp=dict(zip(f.u,f.id_us_node))|dict(zip(f.v,f.id_ds_node))
 if ex not in cache:
  br=release.lookup(ex,'indep','S000_base');cache[ex]=(frame(br['original_frame']).set_index('id_link'),pyogrio.read_dataframe(br['links']).set_index('id_link'),pyogrio.read_dataframe(br['nodes']).set_index('id_node'))
 p,pg,pn=cache[ex];pm=dict(zip(p.u,p.id_us_node))|dict(zip(p.v,p.id_ds_node))
 before=audit['removed_child_links'];after=audit['restored_parent_links'];bounds=pg.loc[after].total_bounds
 if ex=='02' and not key.endswith('unit_16'):
  pt=pn.loc[31].geometry;bounds=[pt.x-170,pt.y-170,pt.x+170,pt.y+170]
 if key in ['37/S051_unit_256','22/S135_unit_211','37/S289_unit_143','15/S113_unit_189']:
  n={'37/S051_unit_256':510,'22/S135_unit_211':419,'37/S289_unit_143':294,'15/S113_unit_189':384}[key];pt=pn.loc[pm[n]].geometry;bounds=[pt.x-70,pt.y-70,pt.x+70,pt.y+70]
 x0,y0,x1,y1=bounds;pad=max(15,.1*max(x1-x0,y1-y0));fig,axes=plt.subplots(1,2,figsize=(11,4.7),constrained_layout=True)
 for ax,fr,geo,ns,mapping,lids,color,title in [(axes[0],f,g,nodes,mp,before,'#d16b28','Current affected reaches'),(axes[1],p,pg,pn,pm,after,'#087f8c','Proposed: restore reference reaches')]:
  labels={}
  for lid in lids:
   q=fr.loc[lid];line=geo.loc[lid].geometry;parts=[line] if line.geom_type=='LineString' else list(line.geoms)
   for part in parts:
    xx,yy=part.xy;ax.plot([x-x0 for x in xx],[y-y0 for y in yy],c=color,lw=2)
   part=max(parts,key=lambda t:t.length);pt=ns.loc[mapping[q.u]].geometry;rev=pt.distance(part.interpolate(0))>pt.distance(part.interpolate(1,normalized=True));a=part.interpolate(.55 if rev else .45,normalized=True);b=part.interpolate(.45 if rev else .55,normalized=True);ax.annotate('',xy=(b.x-x0,b.y-y0),xytext=(a.x-x0,a.y-y0),arrowprops=dict(arrowstyle='->',color=color,lw=1.5))
   for v in [int(q.u),int(q.v)]:
    pt=ns.loc[mapping[v]].geometry;labels.setdefault((pt.x,pt.y),set()).add(v)
  for (x,y),vs in labels.items():
   if x0-pad<=x<=x1+pad and y0-pad<=y<=y1+pad:
    ax.scatter([x-x0],[y-y0],c='#333',s=20);ax.annotate('/'.join(map(str,sorted(vs))),(x-x0,y-y0),xytext=(-18,9) if 651 in vs else (4,5),textcoords='offset points',fontsize=9)
  ax.set_xlim(-pad,x1-x0+pad);ax.set_ylim(-pad,y1-y0+pad);ax.set_aspect('equal');ax.set_title(title);ax.set_xlabel('Local easting (m)');ax.set_ylabel('Local northing (m)')
 b=io.BytesIO();fig.savefig(b,format='png',dpi=110);plt.close(fig);(OUT/(key.replace('/','_')+'_proposal.png')).write_bytes(b.getvalue());c['proposal_image']='data:image/png;base64,'+base64.b64encode(b.getvalue()).decode()
 c['edge_changes']={'remove_current':[dict(link=int(i),u=int(f.loc[i].u),v=int(f.loc[i].v),length_m=float(f.loc[i].link_length_m)) for i in before],'restore_reference':[dict(parent_link=int(i),u=int(p.loc[i].u),v=int(p.loc[i].v),length_m=float(p.loc[i].link_length_m)) for i in after]}
text='''<!doctype html><html><head><meta charset="utf-8"><title>Review proposed boundary fixes</title><style>body{font:16px system-ui;max-width:1250px;margin:30px auto;padding:0 20px;color:#263744;line-height:1.5}header{background:#eef5f7;padding:20px;border-radius:8px}select,button,textarea{font:inherit;padding:8px;margin:4px}textarea{width:95%;min-height:90px}img{max-width:100%;cursor:zoom-in}img.large{max-width:none;width:170%;cursor:zoom-out}pre{white-space:pre-wrap;background:#f4f5f6;padding:15px;font-size:13px}.box{border-left:4px solid #087f8c;padding:8px 18px;margin:20px 0}.choice{border-left-color:#dc8b18}.status{font-weight:bold;color:#087f8c}blockquote{background:#f4f5f6;padding:15px}h2{margin-top:30px}#summary{max-height:250px;overflow:auto}a{cursor:pointer;color:#066b8a;text-decoration:underline}</style></head><body><header><h1>Proposed fixes — your approval review</h1><p>27 individual cases. Nothing has been applied to production. Each proposed fix, its alternative and its implications are stated separately. Accepting a proposal means approving it for an isolated implementation and hydraulic validation, not approving publication of new routing inputs.</p><p><b>Default recommendation:</b> restore original exterior geometry where a concrete local restoration is available. Three suggestions explicitly reverse earlier boundary waivers/merges; those are choices for you, not decisions already made. Two direction reversals and one expanded-scope choice are presented separately.</p><p><b>Validation:</b> 24 proposed graph replacements preserve directed reachability among retained nodes, sources, sinks, components, cycle rank and acyclicity in memory. These checks do not establish geometry attachment or positive-slope feasibility. Maps show only affected reaches; selected-side reattachments are described in the text and are not yet drawn.</p><p>Review each case, select a decision and add notes. All start as <b>Not reviewed</b>. Use Export decisions to return one JSON file. Accepting one repeated case does not accept the others automatically.</p></header><p><button onclick="move(-1)">Previous</button><select id="pick" onchange="show()"></select><button onclick="move(1)">Next</button><span id="progress"></span></p><details><summary>All cases and review status</summary><div id="summary"></div></details><h2 id="title"></h2><p id="kind" class="status"></p><blockquote id="usernote"></blockquote><div class="box"><h3>Recommended fix</h3><p id="action"></p><h3>Boundary contract</h3><p id="boundary"></p><h3>Head / slope treatment</h3><p id="hydraulics"></p></div><div class="box choice"><h3>Alternative — requires a separate choice</h3><p id="alternative"></p></div><div id="preview"></div><details><summary>Current reference-versus-collapse evidence map</summary><div id="evidence"></div></details><details><summary>Exact edge changes and graph checks</summary><pre id="audit"></pre></details><h3>Your decision</h3><select id="decision" onchange="save()"><option>Not reviewed</option><option>Accept recommended fix for isolated testing</option><option>Prefer stated alternative</option><option>Revise proposal — see notes</option><option>Defer / exclude case for now</option></select><br><textarea id="notes" placeholder="Describe any conditions, corrections or which alternative you mean." oninput="save()"></textarea><p><button onclick="download()">Export all decisions as JSON</button><span id="storage"></span></p><p>Browser storage is a convenience. Export your JSON before closing. This page cannot modify geometry or hydraulic files.</p><script>const cases=__DATA__;const storeKey='river-proposed-boundary-fixes-v1-20261027';let reviews={};try{reviews=JSON.parse(localStorage.getItem(storeKey)||'{}')}catch(e){}const el=id=>document.getElementById(id);const pick=el('pick');cases.forEach((c,i)=>pick.add(new Option(c.key+' — '+c.title,i)));function esc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}function show(){const c=cases[+pick.value];for(const k of ['action','boundary','hydraulics','alternative'])el(k).textContent=c[k];el('title').textContent=c.key+' — '+c.title;el('kind').textContent=c.kind;el('usernote').textContent='Your original note: '+c.user_note;el('preview').innerHTML=c.proposal_image?'<h3>Current → proposed geometry (affected reaches only)</h3><p>Click the image to enlarge. Reference IDs on the proposed side are provenance, not a promise to reuse those IDs in production.</p><img alt="Current and proposed affected geometry" onclick="this.classList.toggle(&quot;large&quot;)" src="'+c.proposal_image+'">':'<p><b>No geometry replacement preview:</b> this is a direction/head or explicit-scope decision. The current evidence map below supports your review.</p>';el('evidence').innerHTML=c.evidence_image?'<img alt="Reference and current geometry" onclick="this.classList.toggle(&quot;large&quot;)" src="'+c.evidence_image+'">':'';el('audit').textContent=JSON.stringify({proposal_id:c.proposal_id,edge_changes:c.edge_changes||null,graph_check:c.graph_check},null,2);el('decision').value=reviews[c.key]?.decision||'Not reviewed';el('notes').value=reviews[c.key]?.notes||'';update()}function update(){el('progress').textContent=cases.filter(c=>reviews[c.key]&&reviews[c.key].decision!='Not reviewed').length+' / 27 reviewed';el('summary').innerHTML=cases.map((c,i)=>'<p><a onclick="pick.value='+i+';show()">'+esc(c.key)+'</a> — '+esc(reviews[c.key]?.decision||'Not reviewed')+'</p>').join('')}function save(){const c=cases[+pick.value];reviews[c.key]={proposal_id:c.proposal_id,decision:el('decision').value,notes:el('notes').value};try{localStorage.setItem(storeKey,JSON.stringify(reviews));el('storage').textContent='Saved in this browser.'}catch(e){el('storage').textContent='Browser storage unavailable; export to keep decisions.'}update()}function move(n){pick.value=Math.max(0,Math.min(cases.length-1,+pick.value+n));show()}function download(){const data={review_type:'proposed_boundary_fixes',version:1,production_changes_authorized:false,cases:cases.map(c=>({key:c.key,proposal_id:c.proposal_id,recommended_fix:c.action,alternative:c.alternative,decision:reviews[c.key]?.decision||'Not reviewed',notes:reviews[c.key]?.notes||''}))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='proposed-boundary-fix-decisions.json';a.click();URL.revokeObjectURL(a.href)}show();</script></body></html>'''
(OUT/'review_proposed_fixes.html').write_text(text.replace('__DATA__',json.dumps(proposals).replace('</','<\\/')))
